// Packages:
// - ModelContextProtocol --version 1.*
// - Microsoft.Extensions.Logging

using Microsoft.Extensions.Logging;
using ModelContextProtocol;
using ModelContextProtocol.Server;

// Full tool class with validation and structured error handling
public sealed record ToolError(string Code, string Message, string? Field = null, bool Retryable = false);

public sealed class CreateOrderTool
{
    private readonly ILogger<CreateOrderTool> _logger;

    public CreateOrderTool(ILogger<CreateOrderTool> logger)
    {
        _logger = logger;
    }

    [McpServerTool(Name = "create_order")]
    public async Task<string> ExecuteAsync(
        string customerId,
        List<string>? items = null,
        string priority = "standard",
        CancellationToken ct = default)
    {
        // Validation before business logic
        if (string.IsNullOrWhiteSpace(customerId))
        {
            // Expected error JSON:
            // { "code": "invalid_params", "message": "customerId is required.", "field": "customerId", "retryable": false }
            throw new McpToolException("invalid_params", "customerId is required.", field: "customerId", retryable: false);
        }

        if (items is null || items.Count == 0)
        {
            // Expected error JSON:
            // { "code": "invalid_params", "message": "At least one item is required.", "field": "items", "retryable": false }
            throw new McpToolException("invalid_params", "At least one item is required.", field: "items", retryable: false);
        }

        var allowedPriorities = new[] { "standard", "express", "overnight" };
        if (!allowedPriorities.Contains(priority))
        {
            // Expected error JSON:
            // { "code": "invalid_params", "message": "priority must be one of: standard, express, overnight.", "field": "priority", "retryable": false }
            throw new McpToolException("invalid_params", $"priority must be one of: {string.Join(", ", allowedPriorities)}.", field: "priority", retryable: false);
        }

        try
        {
            _logger.LogInformation("Creating order for {CustomerId} with {ItemCount} items", customerId, items.Count);

            // Simulate order creation
            await Task.Delay(100, ct);

            var orderId = $"ORD-{Random.Shared.Next(1000, 9999)}";

            // Expected success JSON:
            // { "orderId": "ORD-4821", "customerId": "CUST-2001", "status": "created", "priority": "standard" }
            return JsonSerializer.Serialize(new { orderId, customerId, status = "created", priority });
        }
        catch (OperationCanceledException)
        {
            _logger.LogWarning("Order creation cancelled for {CustomerId}", customerId);
            throw new McpToolException("cancelled", "Request was cancelled.", retryable: true);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to create order for {CustomerId}", customerId);
            throw new McpToolException("internal_error", "An unexpected error occurred. Please try again.", retryable: true);
        }
    }
}

